'use strict';

// MODULES //

var Number = require( '@stdlib/number/ctor' );


// MAIN //

/**
* Serializes a k-means clustering results object as a JSON object.
*
* @param {Object} results - k-means clustering results object
* @returns {Object} serialized object
*
* @example
*
* var results = {
*     'replicates': 4,
*     'replicate': 2,
*     'metric': 'sqeuclidean',
*     'iterations': 10,
*     'algorithm': 'lloyd',
*     'inertia': 3.28,
*     'k': 4,
*     'samples': 10,
*     'features': 3,
*     'method': 'K-means clustering'
* };
*
* var obj = toJSON( results );
* // returns {...}
*/
function toJSON( results ) {
	return {
		'replicates': Number( results.replicates ),
		'replicate': Number( results.replicate ),
		'metric': results.metric,
		'iterations': Number( results.iterations ),
		'algorithm': results.algorithm,
		'inertia': results.inertia,
		'k': Number( results.k ),
		'samples': Number( results.samples ),
		'features': Number( results.features ),
		'method': results.method
	};
}


// EXPORTS //

module.exports = toJSON;
